(10,'Half-life of the remaining adjustment',r'\tau_{1/2}=\frac{\log 2}{k}','The remaining-gap half-life differs from time to 50 percent of total adjustment when f is nonzero.'),
(11,'HC3 covariance estimator',r'\widehat V_{\mathrm{HC3}}=(X^{\mathsf T}X)^{-1}\!\left[\sum_e\frac{\hat\varepsilon_e^2\,\mathbf{x}_e^{R}(\mathbf{x}_e^{R})^{\mathsf T}}{(1-\ell_e)^2}\right](X^{\mathsf T}X)^{-1}','Here x superscript R is a regression row, distinct from the rate-input vector; ℓ is OLS leverage.'),
(12,'Event-path wild-bootstrap draw',r'Y^*_{e}(h)=\widehat Y_e(h)+v_e\frac{\widehat\varepsilon_e(h)}{1-\ell_e},\qquad \Pr(v_e=1)=\Pr(v_e=-1)=\tfrac12','One sign per event is shared across all horizons, retaining within-event path dependence.'),
(13,'Simultaneous response band',r'\mathcal{B}_h=\left[\hat\beta_h-c_{0.95}\,\widehat{\mathrm{se}}_h,\ \hat\beta_h+c_{0.95}\,\widehat{\mathrm{se}}_h\right]','The critical value is the 95th percentile of the bootstrap maximum absolute studentised coefficient error across the 20 horizons.'),
(14,'Realised variance in an event window',r'RV_{e,a}=\sum_{t=0}^{19}r_{e,a,t}^{\,2}','Measured in squared basis points and compared with the selected matched weekday.'),
(15,'Paired prediction-loss difference',r'\Delta_{\mathrm{MSE}}=\frac1N\sum_{e=1}^{N}\left[(Y_e-\widehat Y_e)^2-(Y_e-\widehat Y_e^{\,0})^2\right]','Negative values favour the frozen surprise model over the development-mean baseline.'),
(16,'Predictive lead–lag association',r'r^B_{e,t}=\mu_e+\sum_{j=1}^{3}\phi_j r^B_{e,t-j}+\sum_{j=1}^{3}\gamma_j r^A_{e,t-j}+u_{e,t}','Event fixed effects and own-return lags precede exploratory tests of the three cross-series lags; event-cluster uncertainty is approximate.'),
(17,'Monte Carlo standard error',r'\mathrm{MCSE}(\hat p)=\sqrt{\hat p(1-\hat p)/M}','M is the number of independent simulation replications; simulation performance estimates have their own uncertainty.'),
